'use strict';

// Cubic loops with matching tangents retain a straight home stretch and smooth lane offsets.
function fantasyLoop(home, knots) {
  const segs = [{ len: home }]; let a = [home, 0, 0, 60];
  for (const b of knots) {
    const ah = a[2] * Math.PI / 180, bh = b[2] * Math.PI / 180;
    segs.push({ curve: [[a[0] + Math.cos(ah) * a[3], a[1] + Math.sin(ah) * a[3]], [b[0] - Math.cos(bh) * b[3], b[1] - Math.sin(bh) * b[3]], [b[0], b[1]]] }); a = b;
  }
  return segs;
}
